<script setup lang="ts">
import { computed, ref } from 'vue'
import { NAlert, NButton, NCard, NForm, NFormItem, NInput, NProgress, NTag } from 'naive-ui'
import { AuthTokenResponse, createTask, createTaskWithInput, downloadTask, login, logout, ProgressEvent, refresh, register, streamProgress, upload } from './api'

type Session = AuthTokenResponse & { accessTokenExpiresAt: number }
type Activity = { id: string; title: string; detail: string; meta?: string; time: string; kind: 'info' | 'success' | 'warning' | 'error' }
type Stage = { key: string; no: string; title: string; description: string }

const sessionKey = 'report-ai-auth'
const stored = sessionStorage.getItem(sessionKey)
const session = ref<Session | null>(stored ? JSON.parse(stored) as Session : null)
const authMode = ref<'login' | 'register'>('login')
const email = ref(''); const password = ref(''); const displayName = ref(''); const tenantName = ref('')
const file = ref<File | null>(null); const inputFile = ref<File | null>(null); const inputPath = ref('data/input.bin'); const documentId = ref(''); const taskId = ref(''); const status = ref('IDLE')
const percent = ref(0); const message = ref(''); const error = ref(''); const busy = ref(false); const downloading = ref(false)
const warnings = ref<string[]>([]); const activities = ref<Activity[]>([]); const lastEventAt = ref('')
const connectionState = ref<'idle' | 'connecting' | 'live' | 'ended' | 'error'>('idle')
const failedStage = ref<string | null>(null); const activeStage = ref<string | null>(null)

const stages: Stage[] = [
  { key: 'UPLOAD', no: '01', title: 'Upload report', description: 'Receive and validate the DOCX' },
  { key: 'PARSE', no: '02', title: 'Parse document', description: 'Extract structure and placeholders' },
  { key: 'PLAN', no: '03', title: 'Plan experiment', description: 'Create a traceable execution plan' },
  { key: 'CATALOG', no: '04', title: 'Resolve Catalog', description: 'Lock the image, dependencies and hashes' },
  { key: 'PREFLIGHT', no: '05', title: 'Preflight inputs', description: 'Verify data, permissions and resource limits' },
  { key: 'CODE', no: '06', title: 'Generate code', description: 'Write runnable experiment code' },
  { key: 'INSTALL', no: '07', title: 'Install dependencies', description: 'Prepare the ephemeral environment' },
  { key: 'EXECUTE', no: '08', title: 'Run sandbox', description: 'Execute offline with bounded resources' },
  { key: 'ARTIFACTS', no: '09', title: 'Collect artifacts', description: 'Save charts, images, logs and metrics' },
  { key: 'CLEANUP', no: '10', title: 'Cleanup runtime', description: 'Remove temporary containers and volumes' },
  { key: 'REVIEW', no: '11', title: 'Review report', description: 'Check completeness and evidence' },
  { key: 'EXPORT', no: '12', title: 'Export DOCX', description: 'Release the final reproducible report' },
]
const labels: Record<string, string> = { IDLE: 'Ready to start', UPLOADING: 'Uploading report', DOCUMENT_READY: 'Report parsed', CREATED: 'Task queued', QUEUED: 'Task queued', STARTED: 'Agent started', PARSING: 'Parsing document', PLANNING: 'Making execution plan', EXECUTING: 'Running experiment', REVIEWING: 'Reviewing completeness', EXPORTING: 'Building final DOCX', SUCCEEDED: 'Report completed', FAILED: 'Task failed', CANCELLED: 'Task cancelled', RETRY_SCHEDULED: 'Preparing retry' }
const stageForStatus: Record<string, string> = { CREATED: 'PARSE', QUEUED: 'PARSE', STARTED: 'PARSE', PARSING: 'PARSE', PLANNING: 'PLAN', EXECUTING: 'CODE', REVIEWING: 'REVIEW', EXPORTING: 'EXPORT', SUCCEEDED: 'EXPORT', FAILED: 'EXPORT', CANCELLED: 'EXPORT' }
const token = computed(() => session.value?.accessToken ?? '')
const hasDocument = computed(() => Boolean(documentId.value)); const hasTask = computed(() => Boolean(taskId.value))
const terminal = computed(() => ['SUCCEEDED', 'FAILED', 'CANCELLED'].includes(status.value))
const canUpload = computed(() => Boolean(token.value && file.value && !busy.value && !taskId.value))
const currentKey = computed(() => {
  if (!hasDocument.value) return 'UPLOAD'
  if (!hasTask.value) return 'PLAN'
  if (status.value === 'SUCCEEDED') return 'EXPORT'
  if (status.value === 'FAILED' || status.value === 'CANCELLED') return failedStage.value ?? activeStage.value ?? 'PARSE'
  return activeStage.value ?? stageForStatus[status.value] ?? 'PARSE'
})
const currentIndex = computed(() => stages.findIndex(stage => stage.key === currentKey.value))
const currentStage = computed(() => stages.find(stage => stage.key === currentKey.value) ?? stages[0])
const statusLabel = computed(() => labels[status.value] ?? status.value)
const connectionLabel = computed(() => ({ idle: 'Not connected', connecting: 'Connecting events', live: 'Live updates', ended: 'Event stream ended', error: 'Connection error' }[connectionState.value]))
const userInitial = computed(() => (session.value?.displayName || session.value?.email || 'R').slice(0, 1).toUpperCase())

function timeLabel() { return new Intl.DateTimeFormat('en-US', { hour: '2-digit', minute: '2-digit', second: '2-digit' }).format(new Date()) }
function addActivity(title: string, detail: string, kind: Activity['kind'] = 'info', meta = '') { activities.value.unshift({ id: crypto.randomUUID(), title, detail, meta, time: timeLabel(), kind }); activities.value = activities.value.slice(0, 30) }
function saveSession(value: AuthTokenResponse) { const next = { ...value, accessTokenExpiresAt: Date.now() + value.accessTokenExpiresInSeconds * 1000 }; session.value = next; sessionStorage.setItem(sessionKey, JSON.stringify(next)); error.value = '' }
async function accessToken() { if (!session.value) throw new Error('Your session expired. Please sign in again.'); if (session.value.accessTokenExpiresAt > Date.now() + 60000) return session.value.accessToken; const renewed = await refresh(session.value.refreshToken); saveSession(renewed); return renewed.accessToken }
async function submitAuth() { busy.value = true; error.value = ''; try { const result = authMode.value === 'login' ? await login({ email: email.value.trim(), password: password.value }) : await register({ email: email.value.trim(), password: password.value, displayName: displayName.value.trim(), tenantName: tenantName.value.trim() }); saveSession(result); addActivity('Workspace ready', `Signed in as ${result.displayName || result.email}`, 'success') } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Authentication failed.' } finally { busy.value = false } }
async function signOut() { if (session.value?.refreshToken) { try { await logout(session.value.refreshToken) } catch { /* local sign out remains safe */ } } session.value = null; sessionStorage.removeItem(sessionKey); resetWorkspace() }
function resetWorkspace() { file.value = null; inputFile.value = null; inputPath.value = 'data/input.bin'; documentId.value = ''; taskId.value = ''; status.value = 'IDLE'; percent.value = 0; message.value = ''; warnings.value = []; activities.value = []; connectionState.value = 'idle'; lastEventAt.value = ''; failedStage.value = null; activeStage.value = null }
function bytes(size: number) { return size < 1048576 ? `${Math.max(1, Math.round(size / 1024))} KB` : `${(size / 1048576).toFixed(1)} MB` }
function chooseFile(value: File | null) { if (!value) return; if (!value.name.toLowerCase().endsWith('.docx')) { error.value = 'Only .docx reports are supported.'; return }; if (value.size > 52428800) { error.value = 'The file must be smaller than 50 MB.'; return }; file.value = value; error.value = ''; addActivity('Report selected', `${value.name} - ${bytes(value.size)}. Ready to upload.`) }
function dropFile(event: DragEvent) { chooseFile(event.dataTransfer?.files?.[0] ?? null) }
function chooseInputFile(value: File | null) { if (!value) return; if (value.size > 524288000) { error.value = 'The experiment input must be smaller than 512 MB.'; return }; inputFile.value = value; error.value = ''; addActivity('Input selected', `${value.name} - ${bytes(value.size)}. It will be mounted read-only.`) }
async function handleUpload() { if (!file.value || !token.value) return; busy.value = true; error.value = ''; status.value = 'UPLOADING'; percent.value = 4; addActivity('Upload started', 'Writing the report to object storage and sending it to the document parser.'); try { const result = await upload(file.value, await accessToken(), crypto.randomUUID()); documentId.value = result.documentId; warnings.value = result.warnings ?? []; status.value = 'DOCUMENT_READY'; percent.value = 12; message.value = 'Document structure is ready. Start the Agent when you are ready.'; addActivity('Document parsed', `Structure created successfully. Document ID: ${result.documentId}`, 'success'); if (warnings.value.length) addActivity('Parser notes', `${warnings.value.length} note(s) need your attention.`, 'warning') } catch (cause) { status.value = 'FAILED'; error.value = cause instanceof Error ? cause.message : 'Upload and parsing failed.'; addActivity('Upload failed', error.value, 'error') } finally { busy.value = false } }
async function startAgent() { if (!token.value || !documentId.value) return; busy.value = true; error.value = ''; failedStage.value = null; activeStage.value = null; status.value = 'CREATED'; percent.value = 0; message.value = 'Task created. Waiting for the Agent scheduler.'; addActivity('Agent started', 'Planner, Catalog, Preflight, Coder, Installer, Execution, Artifact Persistence, Cleanup, Reviewer and Exporter will collaborate in order.'); try { const auth = await accessToken(); const result = inputFile.value ? await createTaskWithInput(documentId.value, inputPath.value.trim() || 'data/input.bin', inputFile.value, auth, crypto.randomUUID()) : await createTask(documentId.value, auth, crypto.randomUUID()); taskId.value = result.taskId; status.value = result.status || 'CREATED'; void watchProgress(result.taskId) } catch (cause) { status.value = 'FAILED'; failedStage.value = 'PARSE'; error.value = cause instanceof Error ? cause.message : 'Could not create the task.'; addActivity('Task creation failed', error.value, 'error') } finally { busy.value = false } }
function retryTask() { if (!documentId.value || busy.value) return; taskId.value = ''; connectionState.value = 'idle'; activeStage.value = null; addActivity('Retry requested', 'Creating a fresh task with the same parsed document.'); void startAgent() }
function eventStatus(event: ProgressEvent) { const phase = event.attributes?.phase?.toUpperCase(); if (event.type === 'SUCCEEDED') return 'SUCCEEDED'; if (event.type === 'FAILED') return 'FAILED'; if (event.type === 'CANCELLED') return 'CANCELLED'; if (event.type === 'QUEUED' || event.type === 'RETRY_SCHEDULED') return event.type; if (phase === 'PARSING') return 'PARSING'; if (phase === 'PLANNING') return 'PLANNING'; if (phase === 'EXECUTING') return 'EXECUTING'; if (phase === 'REVIEWING') return 'REVIEWING'; if (phase === 'EXPORTING') return 'EXPORTING'; if (phase === 'COMPLETED') return 'SUCCEEDED'; if (event.message.toLowerCase().includes('started')) return 'STARTED'; return status.value }
function stageForEvent(event: ProgressEvent, next: string) { const agent = `${event.attributes?.agent ?? ''}`.toLowerCase(); const text = `${event.message} ${event.attributes?.phase ?? ''} ${agent} ${event.attributes?.agents ?? ''}`.toLowerCase(); if (agent === 'planner') return 'PLAN'; if (agent === 'coder') return 'CODE'; if (agent === 'preflight') return 'PREFLIGHT'; if (agent === 'installer') return 'INSTALL'; if (agent === 'execution' || agent === 'runtime') return 'EXECUTE'; if (agent === 'artifact-persistence') return 'ARTIFACTS'; if (agent === 'cleanup') return 'CLEANUP'; if (agent === 'document' || agent === 'reviewer') return 'REVIEW'; if (text.includes('catalog') || text.includes('resolve')) return 'CATALOG'; if (text.includes('preflight')) return 'PREFLIGHT'; if (text.includes('install') || text.includes('dependency')) return 'INSTALL'; if (text.includes('cleanup') || text.includes('clean up')) return 'CLEANUP'; if (text.includes('artifact') || text.includes('collect')) return 'ARTIFACTS'; if (text.includes('coder') || text.includes('generat')) return 'CODE'; if (text.includes('runtime') || text.includes('sandbox') || text.includes('execut')) return 'EXECUTE'; return stageForStatus[next] ?? null }
function recordEvent(event: ProgressEvent) { const next = eventStatus(event); const nextStage = stageForEvent(event, next); if (nextStage) activeStage.value = nextStage; const detail = event.attributes?.error || event.message || 'The Agent emitted a new progress event.'; const agentMeta = event.attributes?.agents ? `Agents: ${event.attributes.agents}` : event.attributes?.phase ? `Phase: ${event.attributes.phase}` : ''; if (next === 'FAILED' || next === 'CANCELLED') failedStage.value = activeStage.value ?? stageForStatus[status.value] ?? failedStage.value ?? 'PARSE'; status.value = next; percent.value = Math.max(percent.value, event.percent); message.value = detail; lastEventAt.value = event.occurredAt; const kind = next === 'FAILED' ? 'error' : next === 'SUCCEEDED' ? 'success' : next === 'RETRY_SCHEDULED' ? 'warning' : 'info'; if (next === 'FAILED' || next === 'RETRY_SCHEDULED') error.value = detail; addActivity(labels[next] ?? event.type, detail, kind, agentMeta) }
async function watchProgress(id: string) { connectionState.value = 'connecting'; try { await streamProgress(id, await accessToken(), event => { connectionState.value = 'live'; recordEvent(event); if (event.type === 'SUCCEEDED') percent.value = 100 }); connectionState.value = 'ended' } catch (cause) { connectionState.value = 'error'; error.value = cause instanceof Error ? cause.message : 'The live progress connection was interrupted.'; addActivity('Live connection interrupted', 'The task is safe. Reconnect to continue viewing progress.', 'warning') } }
function reconnect() { if (taskId.value) void watchProgress(taskId.value) }
async function exportReport() { if (!taskId.value || status.value !== 'SUCCEEDED') return; downloading.value = true; error.value = ''; try { await downloadTask(taskId.value, await accessToken()); addActivity('Export complete', 'The review-gated task DOCX is in your browser download folder.', 'success') } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Export failed.'; addActivity('Export failed', error.value, 'error') } finally { downloading.value = false } }
function stageClass(index: number) { if (status.value === 'FAILED' && index === currentIndex.value) return 'is-failed'; if (status.value === 'SUCCEEDED' || index < currentIndex.value || (index === 0 && hasDocument.value)) return 'is-done'; if (index === currentIndex.value) return 'is-current'; return 'is-pending' }
</script>

<template>
  <div class="app-shell">
    <header class="topbar"><div class="brand-lockup"><div class="brand-mark">R</div><div><div class="brand-name">ReportAI</div><div class="brand-subtitle">Experiment report Agent workspace</div></div></div><div class="topbar-context"><span class="status-dot" :class="{ online: Boolean(session) }"></span><span>{{ session ? 'Workspace ready' : 'Sign in to begin' }}</span><span class="topbar-divider"></span><span class="muted">Java - PostgreSQL - Docker</span></div><div v-if="session" class="user-menu"><div class="avatar">{{ userInitial }}</div><div class="user-copy"><strong>{{ session.displayName || session.email }}</strong><span>{{ session.email }}</span></div><n-button quaternary size="small" @click="signOut">Sign out</n-button></div></header>
    <div v-if="!session" class="auth-layout"><section class="auth-intro"><span class="eyebrow">AUTOMATED REPORT STUDIO</span><h1>Turn one experiment into a visible delivery pipeline.</h1><p>ReportAI parses your Word file, creates a plan, generates and runs code, collects charts, fills the report, and reviews the final document before export.</p><div class="capability-grid"><div><span class="capability-icon blue">01</span><strong>Understand</strong><small>Goals, tables, questions and placeholders</small></div><div><span class="capability-icon purple">02</span><strong>Execute</strong><small>Code runs in an isolated sandbox</small></div><div><span class="capability-icon orange">03</span><strong>Deliver</strong><small>A reviewed, submission-ready DOCX</small></div></div></section><n-card class="auth-card" :bordered="false"><div class="auth-card-heading"><span class="eyebrow">YOUR WORKSPACE</span><h2>{{ authMode === 'login' ? 'Sign in to workspace' : 'Create your workspace' }}</h2><p>{{ authMode === 'login' ? 'Continue your experiment report task.' : 'Register and upload your first report.' }}</p></div><n-alert v-if="error" type="error" class="inline-alert" :show-icon="false">{{ error }}</n-alert><n-form label-placement="top" @submit.prevent="submitAuth"><n-form-item label="Email"><n-input v-model:value="email" size="large" autocomplete="email" placeholder="you@example.com" /></n-form-item><n-form-item label="Password"><n-input v-model:value="password" size="large" type="password" show-password-on="click" autocomplete="current-password" placeholder="At least 12 characters" /></n-form-item><template v-if="authMode === 'register'"><n-form-item label="Display name"><n-input v-model:value="displayName" size="large" placeholder="Your name" /></n-form-item><n-form-item label="Workspace name"><n-input v-model:value="tenantName" size="large" placeholder="My laboratory" /></n-form-item></template><n-button block size="large" type="primary" :loading="busy" attr-type="submit">{{ authMode === 'login' ? 'Enter workspace' : 'Create workspace' }}</n-button></n-form><button class="auth-switch" type="button" @click="authMode = authMode === 'login' ? 'register' : 'login'">{{ authMode === 'login' ? 'No account? Create a workspace' : 'Already have an account? Sign in' }}</button></n-card></div>
    <main v-else class="workspace-shell">
      <aside class="sidebar"><div class="sidebar-section sidebar-intro"><span class="eyebrow">WORKSPACE</span><h2>Report delivery center</h2><p>Every step from source document to final report, visible.</p></div><nav class="sidebar-nav" aria-label="Workspace navigation"><div class="nav-item is-active"><span class="nav-icon">HOME</span><span>Current task</span><span v-if="hasTask" class="nav-count">1</span></div><div class="nav-item"><span class="nav-icon">DOC</span><span>Recent reports</span></div><div class="nav-item"><span class="nav-icon">AI</span><span>Agent capabilities</span></div></nav><div class="sidebar-section recent-section"><div class="section-heading"><span>THIS WORKSPACE</span><span class="live-pill"><i></i> LIVE</span></div><div class="recent-item" :class="{ 'has-task': hasTask }"><div class="document-glyph">W</div><div class="recent-copy"><strong>{{ file?.name || 'Waiting for a report' }}</strong><span>{{ hasTask ? statusLabel : hasDocument ? 'Parsed - ready to start' : 'DOCX - up to 50 MB' }}</span></div></div></div><div class="sidebar-footnote"><span class="shield">SAFE</span><div><strong>Safe execution environment</strong><p>Generated code runs inside an isolated Docker sandbox.</p></div></div></aside>
      <section class="main-column"><div class="page-heading"><div><span class="eyebrow">AGENT WORKSPACE</span><h1>{{ hasTask ? 'Completing your experiment report' : hasDocument ? 'Report ready - start the Agent' : 'Start with an experiment report' }}</h1><p>{{ hasTask ? 'See every Agent action, live log and generated artifact here.' : hasDocument ? 'The parser built your document structure. The Agent is ready to plan and execute.' : 'Upload a .docx report, inspect the parsed state, then choose when to run the Agent.' }}</p></div><div class="heading-actions"><n-tag v-if="hasTask" :type="terminal ? (status === 'SUCCEEDED' ? 'success' : 'error') : 'info'" round>{{ statusLabel }}</n-tag><n-button v-if="hasDocument && !hasTask" secondary @click="resetWorkspace">Choose another</n-button></div></div><n-alert v-if="error" type="error" class="workspace-alert" :show-icon="false" closable @close="error = ''"><strong>{{ status === 'FAILED' ? 'This task did not complete' : 'Action could not be completed' }}</strong><span>{{ error }}</span></n-alert>
        <section class="upload-panel panel"><div class="panel-heading"><div><span class="eyebrow">START HERE</span><h2>Import experiment report</h2></div><span class="panel-index">01 / 02</span></div><div class="dropzone" :class="{ 'has-file': Boolean(file), disabled: hasTask }" @dragover.prevent @drop.prevent="dropFile"><input id="report-file" class="visually-hidden" type="file" accept=".docx,application/vnd.openxmlformats-officedocument.wordprocessingml.document" :disabled="hasTask" @change="chooseFile(($event.target as HTMLInputElement).files?.[0] ?? null)" /><label for="report-file" class="dropzone-content"><div class="upload-orb">UP</div><div v-if="file" class="selected-file"><strong>{{ file.name }}</strong><span>{{ bytes(file.size) }} - {{ hasDocument ? 'Parsed' : 'Ready to upload' }}</span></div><div v-else><strong>Drop a Word report here, or choose a file</strong><span>.docx only - max 50 MB</span></div></label></div><div class="input-row"><label for="experiment-input">Optional experiment data</label><input id="experiment-input" type="file" :disabled="hasTask" @change="chooseInputFile(($event.target as HTMLInputElement).files?.[0] ?? null)" /><input v-model="inputPath" class="input-path" :disabled="hasTask" aria-label="Input path in sandbox" placeholder="data/input.bin" /><small v-if="inputFile">{{ inputFile.name }} - mounted read-only before preflight</small><small v-else>Leave empty for documents that do not require external data.</small></div><div class="panel-actions"><n-button type="primary" size="large" :disabled="!canUpload" :loading="busy && status === 'UPLOADING'" @click="handleUpload">Upload and parse</n-button><n-button v-if="hasDocument && !hasTask" type="success" size="large" :loading="busy && status === 'CREATED'" @click="startAgent">Start Agent automation</n-button><span v-if="hasDocument && !hasTask" class="action-hint"><b>Next:</b> plan, code, run, review and fill the Word report</span><span v-else-if="!hasDocument" class="action-hint">Parsing happens first. Nothing runs until you start the Agent.</span></div></section>
        <section v-if="hasDocument || hasTask" class="process-panel panel"><div class="panel-heading process-heading"><div><span class="eyebrow">VISIBLE PIPELINE</span><h2>{{ hasTask ? 'Agent execution' : 'Document status' }}</h2></div><div v-if="hasTask" class="connection-state" :class="`is-${connectionState}`"><i></i>{{ connectionLabel }}</div></div><div v-if="hasTask" class="progress-overview"><div class="progress-copy"><strong>{{ statusLabel }}</strong><span>{{ message || currentStage.description }}</span></div><div class="progress-number">{{ percent }}<small>%</small></div><n-progress :percentage="percent" :status="status === 'FAILED' ? 'error' : status === 'SUCCEEDED' ? 'success' : undefined" :processing="!terminal" :show-indicator="false" /></div><div v-else class="ready-callout"><span class="ready-icon">READY</span><div><strong>Document structure is ready</strong><p>Click "Start Agent automation" above to begin the real execution flow.</p></div></div><div class="timeline"><div v-for="(stage, index) in stages" :key="stage.key" class="timeline-step" :class="stageClass(index)"><div class="timeline-marker"><span v-if="stageClass(index) === 'is-done'">OK</span><span v-else>{{ stage.no }}</span></div><div class="timeline-line" v-if="index < stages.length - 1"></div><div class="timeline-copy"><strong>{{ stage.title }}</strong><span>{{ stage.description }}</span></div></div></div></section>
        <section v-if="hasTask" class="activity-panel panel"><div class="panel-heading"><div><span class="eyebrow">AGENT ACTIVITY</span><h2>Live execution log</h2><p class="panel-subtitle">Auditable task events only - no hidden chain-of-thought is exposed.</p></div><n-button v-if="connectionState === 'error' || connectionState === 'ended'" text type="primary" @click="reconnect">Reconnect progress</n-button></div><div v-if="activities.length" class="activity-list"><div v-for="activity in activities" :key="activity.id" class="activity-row"><span class="activity-marker" :class="`is-${activity.kind}`"></span><div class="activity-content"><strong>{{ activity.title }}</strong><span>{{ activity.detail }}</span><em v-if="activity.meta">{{ activity.meta }}</em></div><time>{{ activity.time }}</time></div></div><div v-else class="activity-empty">When the Agent connects, parsing, planning, code generation, execution and review events appear here.</div></section>
      </section>
      <aside class="inspector"><section class="inspector-card highlight-card"><div class="inspector-label">CURRENT STEP</div><div class="current-step-number">{{ hasTask ? currentStage.no : '01' }}</div><h2>{{ hasTask ? currentStage.title : hasDocument ? 'Start Agent' : 'Choose report' }}</h2><p>{{ hasTask ? currentStage.description : hasDocument ? 'The report is parsed. The Agent has not started yet.' : 'Upload a .docx experiment report to start your first automated delivery.' }}</p><n-button v-if="hasDocument && !hasTask" block type="primary" size="large" @click="startAgent">Start now</n-button><n-button v-if="status === 'FAILED'" block type="primary" size="large" :loading="busy" @click="retryTask">Retry task</n-button><n-button v-if="status === 'SUCCEEDED'" block type="success" size="large" :loading="downloading" @click="exportReport">Download final Word</n-button><n-button v-if="status === 'FAILED' && taskId" block secondary @click="reconnect">View task state</n-button></section><section class="inspector-card"><div class="inspector-card-heading"><h3>Document and task</h3><span class="small-label">DETAILS</span></div><dl class="detail-list"><div><dt>File</dt><dd>{{ file?.name || '-' }}</dd></div><div><dt>Document status</dt><dd><span class="mini-status" :class="{ ready: hasDocument }"></span>{{ hasDocument ? 'Parsed' : 'Waiting' }}</dd></div><div><dt>Task ID</dt><dd class="mono">{{ taskId ? `${taskId.slice(0, 8)}...` : 'Not created' }}</dd></div><div><dt>Last event</dt><dd>{{ lastEventAt ? new Date(lastEventAt).toLocaleTimeString() : 'Waiting for Agent' }}</dd></div></dl></section><section class="inspector-card capability-card"><div class="inspector-card-heading"><h3>What the Agent will do</h3><span class="small-label">5 AGENTS</span></div><div class="agent-chip"><span class="agent-avatar planner">P</span><div><strong>Planner</strong><small>Break down goals and plan execution</small></div></div><div class="agent-chip"><span class="agent-avatar coder">C</span><div><strong>Coder + Runtime</strong><small>Generate code and run it safely</small></div></div><div class="agent-chip"><span class="agent-avatar reviewer">R</span><div><strong>Document + Reviewer</strong><small>Fill the report and check omissions</small></div></div></section><section v-if="warnings.length" class="inspector-card warning-card"><div class="inspector-card-heading"><h3>Parser notes</h3><span class="small-label">{{ warnings.length }}</span></div><ul><li v-for="warning in warnings" :key="warning">{{ warning }}</li></ul></section></aside>
    </main>
    <footer class="footer"><span>ReportAI - Automated document completion platform</span><span>All generated code runs in an isolated sandbox</span></footer>
  </div>
</template>
